<?php /** @var array<string,mixed> $p */ /** @var list<array<string,mixed>> $history */ use Vertex\Core\View; ?>
<div class="page-head"><div><p class="eyebrow">Payout request</p><h1><?= e($p['reference']) ?></h1></div><a class="btn btn-ghost" href="/partner/payouts">&larr; My payouts</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('pbadge', ['kind' => 'payout', 's' => $p['status']]) ?></div><div><span class="muted">Amount</span><br><?= e(money($p['amount_minor'])) ?></div>
    <div><span class="muted">Requested</span><br><?= e(local_time($p['requested_at'])) ?></div><div><span class="muted">Pay to</span><br><?= e((string) $p['details_hint']) ?></div></div>
    <?php if ($p['reason']) : ?><h3>Message from our team</h3><p class="prewrap"><?= e($p['reason']) ?></p><?php endif; ?>
    <?php if ($p['status'] === 'paid') : ?><h3>Payment</h3><p><?= e(config("referrals.payment_methods.{$p['payment_method']}", $p['payment_method'])) ?> · <?= e(local_date($p['payment_date'])) ?> · reference <?= e($p['payment_reference']) ?></p><?php endif; ?>
    <?php if (in_array($p['status'], ['approved', 'processing'], true)) : ?><p>Approved. Our team still has to make and record the payment: it is not paid yet.</p><?php endif; ?>
    <?php if (in_array($p['status'], ['requested', 'under_review'], true)) : ?><form method="post" action="/partner/payouts/<?= e($p['public_id']) ?>/cancel" data-confirm="Cancel this request?" class="inline-form"><?= csrf_field() ?><button class="btn btn-ghost btn-sm" type="submit">Cancel this request</button></form><?php endif; ?></div>
<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($history as $h) : ?><li><strong><?= e(config("referrals.payout_statuses.{$h['to_status']}", $h['to_status'])) ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?></span><?php if ($h['note']) : ?><p class="prewrap"><?= e($h['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div>
